const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

function spyLedger() {
  const ledger = new Ledger(); let calls = 0;
  const apply = ledger.apply.bind(ledger);
  ledger.apply = (...a) => { calls++; return apply(...a); };
  return { ledger, calls: () => calls };
}

async function main() {
  // Repeated equal call returns original receipt, one debit.
  { const { ledger } = spyLedger(); const acks = [];
    const s = new PaymentService(ledger, { acknowledge: async r => { acks.push(r); } });
    const a = await s.pay('t', 'k', 5); const b = await s.pay('t', 'k', 5);
    assert.deepEqual(a, b); assert.equal(ledger.entries.length, 1); assert.equal(acks.length, 2); }

  // Concurrent equal calls: one debit, same receipt.
  { const { ledger } = spyLedger();
    const s = new PaymentService(ledger, { acknowledge: async () => {} });
    const rs = await Promise.all([1, 2, 3, 4].map(() => s.pay('t', 'k', 7)));
    assert.equal(ledger.entries.length, 1);
    for (const r of rs) assert.deepEqual(r, rs[0]); }

  // Same key, different amount: key conflict, no extra debit. Scoped by tenant.
  { const { ledger } = spyLedger(); const s = new PaymentService(ledger, { acknowledge: async () => {} });
    await s.pay('t', 'k', 5);
    await assert.rejects(s.pay('t', 'k', 6), /key conflict/);
    assert.equal(ledger.entries.length, 1);
    await s.pay('other', 'k', 6); assert.equal(ledger.entries.length, 2); }

  // Transient after commit: retried with same receipt, no second debit.
  { const { ledger, calls } = spyLedger(); const seen = []; let n = 0;
    const s = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (n++ < 2) throw new Transient('x'); } });
    const r = await s.pay('t', 'k', 9, 3);
    assert.equal(ledger.entries.length, 1); assert.equal(calls(), 1);
    assert.equal(seen.length, 3); for (const x of seen) assert.deepEqual(x, r); }

  // Exhausted retries rethrow the final Transient instance; exactly `attempts` tries.
  { const { ledger } = spyLedger(); let tries = 0; const last = [];
    const s = new PaymentService(ledger, { acknowledge: async () => { tries++; const e = new Transient('t' + tries); last.push(e); throw e; } });
    await assert.rejects(s.pay('t', 'k', 1, 4), e => e === last[3]);
    assert.equal(tries, 4); assert.equal(ledger.entries.length, 1); }

  // Non-Transient errors are not retried.
  { const { ledger } = spyLedger(); let tries = 0;
    const boom = new Error('boom');
    const s = new PaymentService(ledger, { acknowledge: async () => { tries++; throw boom; } });
    await assert.rejects(s.pay('t', 'k', 1, 5), e => e === boom); assert.equal(tries, 1); }

  // Transient from the ledger is retried; non-Transient ledger error is not.
  { let tries = 0; const ledger = { apply: async () => { tries++; if (tries < 2) throw new Transient('l'); return { id: 1, tenant: 't', key: 'k', cents: 1 }; } };
    const s = new PaymentService(ledger, { acknowledge: async () => {} });
    await s.pay('t', 'k', 1); assert.equal(tries, 2); }

  // Validation happens before any ledger or transport action.
  { const { ledger, calls } = spyLedger(); let acks = 0;
    const s = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    const bad = [['', 'k', 1], ['t', '', 1], ['t', 'k', 0], ['t', 'k', 1.5], ['t', 'k', -1], ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 1.5], [null, 'k', 1], ['t', 'k', 1, '2']];
    for (const args of bad) await assert.rejects(s.pay(...args), /^Error: invalid payment$/);
    assert.equal(calls(), 0); assert.equal(acks, 0); assert.equal(ledger.entries.length, 0); }
  console.log('idempotency checks passed');
}
module.exports = main();
EOF
